function dft(samples, sampleRate){
  var n=samples.length, out=[];
  for(var k=0; k<Math.floor(n/2); k++){
    var re=0, im=0;
    for(var t=0; t<n; t++){
      var ang=-2*Math.PI*k*t/n;
      re+=samples[t]*Math.cos(ang);
      im+=samples[t]*Math.sin(ang);
    }
    out.push({ bin:k, freq:k*sampleRate/n, mag:Math.sqrt(re*re+im*im)/n*2 });
  }
  return out;
}
function peakBin(spectrum){ var bi=0, bm=0; for(var i=0;i<spectrum.length;i++){ if(spectrum[i].mag>bm){ bm=spectrum[i].mag; bi=i; } } return bi; }
function sine(freq, n, sampleRate, amp){ var s=[]; for(var t=0;t<n;t++){ s.push(amp*Math.sin(2*Math.PI*freq*t/sampleRate)); } return s; }
var EXPORTS={ dft:dft, peakBin:peakBin, sine:sine };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpectrumForgePure = EXPORTS; }
